## 变更
- 设备行新增剪贴板按钮，打开面板：输入文本一键写入手机剪贴板（⌘↩），或读取手机剪贴板到刘海并同时复制到 Mac 剪贴板。
- Android 没有读写剪贴板的 shell 命令：脚本内嵌一个约 5 KB 的 dex（`NotchClip`，源码见下），首次使用时按内容哈希命名推送到 `/data/local/tmp`，以 shell 身份经 `app_process` 反射调用系统 `IClipboard`（与 scrcpy 同一思路），手机上不安装任何 App。
- Android 14+ 锁屏期间系统一律拒绝读取剪贴板，面板会明确提示「已锁屏 · 解锁后才能读取」，不误报为空。
- 小组件声明 `wants_text_input`（输入框需要键盘）。
- 已在 Xiaomi 14（HyperOS 3 / Android 16）上实测写入与锁屏检测。

<details><summary>NotchClip.java（内嵌 dex 的源码，d8 --release --min-api 21 编译）</summary>

```java
import android.content.ClipData;
import android.os.IBinder;
import android.util.Base64;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;

// 以 shell 身份经 app_process 读写系统剪贴板（参数签名随系统版本变化，按类型反射填充）
public final class NotchClip {
    private static final String PKG = "com.android.shell";

    public static void main(String[] args) {
        try {
            Object cb = service("clipboard", "android.content.IClipboard");
            String cmd = args.length > 0 ? args[0] : "";
            if (cmd.equals("get")) {
                ClipData clip = (ClipData) call(cb, "getPrimaryClip", null);
                if (clip == null || clip.getItemCount() == 0) {
                    // Android 14+ 锁屏期间一律读不到剪贴板，单独报出来以免误判为空
                    System.out.println(locked() ? "LOCKED" : "EMPTY");
                    return;
                }
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < clip.getItemCount(); i++) {
                    CharSequence text = clip.getItemAt(i).getText();
                    if (text == null) text = clip.getItemAt(i).getHtmlText();
                    if (text == null) continue;
                    if (sb.length() > 0) sb.append('\n');
                    sb.append(text);
                }
                System.out.println(sb.length() == 0 ? "NONTEXT"
                        : "OK " + Base64.encodeToString(sb.toString().getBytes(StandardCharsets.UTF_8), Base64.NO_WRAP));
            } else if (cmd.equals("set")) {
                ByteArrayOutputStream buf = new ByteArrayOutputStream();
                InputStream in = System.in;
                byte[] chunk = new byte[8192];
                for (int n; (n = in.read(chunk)) > 0; ) buf.write(chunk, 0, n);
                String b64 = new String(buf.toByteArray(), StandardCharsets.US_ASCII).trim();
                String text = new String(Base64.decode(b64, Base64.DEFAULT), StandardCharsets.UTF_8);
                call(cb, "setPrimaryClip", ClipData.newPlainText("NotchAny", text));
                System.out.println("OK");
            } else {
                System.out.println("ERR usage: get | set (base64 on stdin)");
                System.exit(2);
            }
        } catch (Throwable e) {
            while (e instanceof InvocationTargetException && e.getCause() != null) e = e.getCause();
            System.out.println("ERR " + e.getClass().getSimpleName() + ": " + e.getMessage());
            System.exit(1);
        }
    }

    private static Object service(String name, String iface) throws Exception {
        Object binder = Class.forName("android.os.ServiceManager").getMethod("getService", String.class).invoke(null, name);
        return Class.forName(iface + "$Stub").getMethod("asInterface", IBinder.class).invoke(null, binder);
    }

    private static boolean locked() {
        try {
            return Boolean.TRUE.equals(call(service("trust", "android.app.trust.ITrustManager"), "isDeviceLocked", null));
        } catch (Throwable e) {
            return false;
        }
    }

    private static Object call(Object cb, String name, ClipData clip) throws Exception {
        for (Method m : cb.getClass().getMethods()) {
            if (!m.getName().equals(name)) continue;
            Class<?>[] types = m.getParameterTypes();
            Object[] args = new Object[types.length];
            boolean pkgSet = false;
            for (int i = 0; i < types.length; i++) {
                if (types[i] == ClipData.class) args[i] = clip;
                else if (types[i] == String.class) { args[i] = pkgSet ? null : PKG; pkgSet = true; }
                else if (types[i] == int.class) args[i] = 0;  // userId / deviceId 取默认 0
                else if (types[i] == boolean.class) args[i] = true;
                else throw new NoSuchMethodException(m.toString());
            }
            return m.invoke(cb, args);
        }
        throw new NoSuchMethodException(name);
    }
}
